package com.primehr.migration;
import org.flywaydb.core.Flyway;import org.flywaydb.core.api.MigrationVersion;import org.junit.jupiter.api.Test;import java.sql.DriverManager;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;
class PrimeHrV36ToV37UpgradeTest {
 @Test void populatedPerformanceDataSurvivesLdFoundationMigration()throws Exception{String db="primehr_v37_"+UUID.randomUUID().toString().replace("-","");String url="jdbc:h2:mem:"+db+";MODE=PostgreSQL;DB_CLOSE_DELAY=-1";Map<String,String>p=Map.of("primehrSchema","PUBLIC");Flyway initial=Flyway.configure().dataSource(url,"sa","").locations("classpath:db/migration/postgresql").schemas("PUBLIC").defaultSchema("PUBLIC").placeholders(p).target(MigrationVersion.fromVersion("36")).cleanDisabled(false).load();initial.migrate();String id=UUID.randomUUID().toString();try{try(var c=DriverManager.getConnection(url,"sa","");var s=c.createStatement()){s.executeUpdate("INSERT INTO PUBLIC.spms_objective (id,agency_id,code,normalized_code,record_version,created_by,created_at,updated_by,updated_at) VALUES ('"+id+"','UPGRADE-37','OBJ','OBJ',0,'test',CURRENT_TIMESTAMP,'test',CURRENT_TIMESTAMP)");}Flyway upgraded=Flyway.configure().dataSource(url,"sa","").locations("classpath:db/migration/postgresql").schemas("PUBLIC").defaultSchema("PUBLIC").placeholders(p).target(MigrationVersion.fromVersion("37")).cleanDisabled(false).load();upgraded.migrate();assertThat(upgraded.info().current().getVersion().getVersion()).isEqualTo("37");try(var c=DriverManager.getConnection(url,"sa","");var existing=c.createStatement().executeQuery("SELECT COUNT(*) FROM PUBLIC.spms_objective WHERE id='"+id+"'")){existing.next();assertThat(existing.getLong(1)).isOne();}try(var c=DriverManager.getConnection(url,"sa","");var fresh=c.createStatement().executeQuery("SELECT COUNT(*) FROM PUBLIC.ld_governance_policy")){fresh.next();assertThat(fresh.getLong(1)).isZero();}}finally{initial.clean();}}
}
